INSERT INTO `faqs` (`id`, `category`, `question`, `answer`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Account Management', 'How do I change my Password?', 'To change your password on the Tirtheasy web, please follow these steps:\r\n\r\nLog in to your Tirtheasy account.\r\nClick your profile picture situated at the top right corner of the page and click on \"Profile\".\r\nOnce on the \"Profile\" page, select \"Edit\" next to the Password Field\r\nYou will need to enter your current password and then enter your new password. Confirm the new password by retyping it.\r\nAfter you\'ve entered all the information, click on \"Save\" to change your password.\r\nPlease note, for security reasons, it is recommended that your password should include a combination of characters, numbers, and symbols. Make sure your password is unique and not easily guessable.', 1, '2025-09-10 14:40:27', '2025-09-16 15:03:45'),
(2, 'Account Management', 'How do I sign in to Tirtheasy?', 'On Web version of Tirtheasy,\r\n\r\nClick on \"Sign In\" at the top-right corner of the page.\r\nA new page will open where you can input your registered email address and password.\r\nAfter filling in your credentials, press the \"Sign In\" button.\r\nIf you have linked your Google or Facebook account to Tirtheasy, you can also choose to sign in using these options, simply by clicking on the respective icons.\r\n\r\nOn mobile/App,\r\n\r\nOn the bottom right corner of the page, you\'ll find the \"More\" button. Click on it.\r\nAt the top right of this page, you\'ll find the \"Login/Sign up\" button. Click on it.\r\nA new page will open where you can input your registered email address and password.\r\nAfter filling in your credentials, press the \"Sign In\" button.\r\nIf you have forgotten your password, just click on the \"Forgot password?\" link and follow the instructions to reset it.', 1, '2025-09-10 14:40:49', '2025-09-16 15:02:55'),
(3, 'Account Management', 'How do I create an account?', 'On Web version of Tirtheasy,\r\n\r\nOn the top right corner of the page, you\'ll find the \"Sign In\" button. Click on it.\r\nAt the bottom of this new page, you\'ll find the \"Create account\" option. Click on it.\r\nYou can choose to sign up using an existing Google, Facebook or Apple ID account. Alternatively, you can sign up with your email. Filling in your First Name, Last Name and Email, you\'ll be asked to create a password.\r\nAfter filling in the information, click on \"Sign Up\".\r\nYou\'ll receive a verification email in your inbox. Click on the link in the email to verify your account.\r\nOn mobile/App,\r\n\r\nOn the bottom right corner of the page, you\'ll find the \"More\" button. Click on it.\r\nAt the top right of this page, you\'ll find the \"Login/Sign up\" button. Click on it.\r\nAt the bottom left of this new page below the \"Sign in\" button, you\'ll find the \"Create account\" option. Click on it.\r\nYou can choose to sign up using an existing Google, Facebook or Apple ID account. Alternatively, you can sign up with your email. Filling in your First Name, Last Name and Email, you\'ll be asked to create a password.\r\nAfter filling in the information, click on \"Sign Up\".\r\nYou\'ll receive a verification email in your inbox. Click on the link in the email to verify your account.\r\nRemember, your Tirtheasy account allows you to manage your bookings, reviews, and settings for a personalized experience. Welcome to Tirtheasy!', 1, '2025-09-10 14:41:07', '2025-09-16 15:02:11'),
(4, 'Booking Details', 'Where can I check my booking details and status?', 'You can always view your booking details and status online by signing in and selecting \"My bookings\" from the account menu. If you don\'t know your sign in details, you can follow the \"My bookings\" link in your confirmation email.', 1, '2025-09-16 15:04:08', '2025-09-16 15:04:08'),
(5, 'Cancellation', 'How can I cancel my booking?', 'You can cancel your booking online on the Tirtheasy website or app. Any cancellation fees are determined by the property and listed in your cancellation policy.', 1, '2025-09-16 15:04:30', '2025-09-16 15:04:30'),
(6, 'Cancellation', 'Will I be charged if I cancel my booking?', 'If you have a free cancellation booking, you will not incur a cancellation fee. If your booking is no longer free to cancel or is non-refundable, you may incur a cancellation fee. The property determines any cancellation fees for a booking.', 1, '2025-09-16 15:04:58', '2025-09-16 15:05:05'),
(7, 'Cancellation', 'How do I know if my booking was cancelled?', 'If you have a free cancellation booking, you will not incur a cancellation fee. If your booking is no longer free to cancel or is non-refundable, you may incur a cancellation fee. The property determines any cancellation fees for a booking.', 1, '2025-09-16 15:05:25', '2025-09-16 15:05:25'),
(8, 'Cancellation', 'How do I know if my booking was cancelled?', 'After you cancel a booking with us, you should receive an email confirming the cancellation. Check your inbox and spam/junk mail folders.', 1, '2025-09-16 15:05:40', '2025-09-16 15:05:40'),
(9, 'Payment/Refund Information', 'When will I get my refund?', 'Refund Initiation: Once your cancellation is confirmed, we will immediately begin processing your refund. This typically happens within 24–48 hours after the cancellation request. Do note that, depending on the payment methods, some refunds need to be initiated through a cancellation email.\r\n\r\nProcessing Time: The exact timing for the refund to reflect in your account depends on the payment method you used at the time of booking:\r\n\r\nCredit/Debit Cards: For most countries, It can take up to 30 business days for the refund to appear on your statement, depending on your card issuer\'s policies. Note that this does not apply to all countries.\r\n\r\nBank Transfer/Online Payment: Refunds processed to your bank account usually take 7–10 business days, though this may vary based on your bank\'s processing times.\r\n\r\nPayPal: Refunds to PayPal accounts are often completed within 3–5 business days.\r\n\r\nOver-the-Counter Payments: These refunds may take up to 15 business days to process, depending on the service provider and the country.\r\n\r\nTirtheasyCash: The refund will be immediate if the TirtheasyCash is not expired.\r\n\r\nCommunication and Updates: You’ll receive a confirmation email once the refund is processed on Tirtheasy\'s side. Your financial institution or service provider may also send you a notification once the funds are credited back to your account. Please keep an eye on your email and bank/PayPal notifications for any updates regarding your refund. Also check your spam folders.', 1, '2025-09-16 15:06:33', '2025-09-16 15:06:33'),
(10, 'Payment/Refund Information', 'Am I eligible for a refund?', 'Whether you\'re eligible for a refund depends on several factors, including the specific terms and conditions of the room or property you booked, and the timing of your cancellation. Here’s how to check your eligibility for a refund:\r\n\r\nReview Your Booking Conditions: The refund policy is specified in the booking confirmation email and the booking details on your Tirtheasy account. Each hotel or property has its own cancellation policy, which was agreed upon during the booking process.\r\n\r\nProcessing Time: To request a cancellation, you can use the self-service option in the \'Manage my Booking\' section on our website, or contact our customer service if you need assistance.\r\n\r\nRefund Process: If your booking is eligible for a refund based on the cancellation policy, Tirtheasy will initiate the refund process once your cancellation is confirmed.\r\n\r\nRefund Timing: Please note that while Tirtheasy  processes refunds promptly upon cancellation confirmation, the time it takes for the funds to appear back in your account can vary. It most commonly depends on the payment method used at the time of booking. Please refer to \"When will I get my refund?\" for more information', 1, '2025-09-16 15:07:09', '2025-09-16 15:07:09'),
(11, 'Manage Guest', 'I want to change the name of the lead guest. How can I do this?', 'Tirtheasy now provides you with a self-service option. Select your booking and update the guest name.', 1, '2025-09-16 15:07:59', '2025-09-16 15:07:59'),
(12, 'Booking Confirmation', 'When do I get a confirmation email?', 'In most cases, you will receive this email along with the booking voucher (PDF file) within 30 minutes of booking. If you still haven\'t received it after that time, please check your junk mail and/or spam filters. You can also download or resend your booking voucher online.', 1, '2025-09-16 15:08:24', '2025-09-16 15:08:24'),
(13, 'Booking Confirmation', 'Can you resend the booking voucher to me?', 'Tirtheasy now provides you with a self-service option. Just by clicking on the self-service link provided in your confirmation email, you will be able to resend your booking voucher.', 1, '2025-09-16 15:08:51', '2025-09-16 15:08:51'),
(14, 'Special Requests', 'How can I make a special request?', 'You can send your special requests to the property using the self-service option. Please note that all special requests are subject to availability and cannot be guaranteed by Tirtheasy.', 1, '2025-09-16 15:09:25', '2025-09-16 15:09:25'),
(15, 'Special Requests', 'How will I know if a special request is confirmed?', 'All special requests are subject to availability and cannot be guaranteed by Tirtheasy. Tirtheasy will forward your request to your preferred property upon receipt, and you can follow up with the property before or upon arrival.', 1, '2025-09-16 15:09:49', '2025-09-16 15:09:59');
